// Block (composition) — API key creation and a responsive list of revocable masked keys.
// Form controls and status Components own their look; this Block only wires and arranges them.
import type { FormEvent, Ref } from "react";
import { Badge } from "../components/Badge";
import { Button } from "../components/Button";
import { Form } from "../components/Form";
import { Separator } from "../components/Separator";
import { Stack } from "../layouts/Stack";
import { TextField } from "../components/TextField";
import "./ApiKeyManager.css";

export interface ApiKeyManagerProps {
  keys: {
    id: string;
    label: string;
    maskedKey: string;
    created?: string;
  }[];
  onCreate?: (label: string) => void;
  onRevoke?: (id: string) => void;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function ApiKeyManager({ keys, onCreate, onRevoke, className, ref }: ApiKeyManagerProps) {
  const handleCreate = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    onCreate?.(String(data.get("label") ?? ""));
  };

  return (
    <Stack
      as="section"
      ref={ref}
      aria-label="API keys"
      gap="medium"
      className={className ? `sd-apikeymanager ${className}` : "sd-apikeymanager"}
    >
      <Form onSubmit={handleCreate}>
        <Stack
          direction={{ small: "column", medium: "row" }}
          gap="small"
          align={{ medium: "end" }}
          className="sd-apikeymanager__create"
        >
          <TextField
            className="sd-apikeymanager__label-field"
            name="label"
            label="Key label"
            placeholder="Production deployment"
            isRequired
          />
          <Button type="submit" variant="primary">Create key</Button>
        </Stack>
      </Form>
      <Separator />
      <Stack gap="small" className="sd-apikeymanager__list">
        {keys.map((key) => (
          <Stack
            key={key.id}
            direction={{ small: "column", medium: "row" }}
            justify="between"
            align={{ small: "stretch", medium: "center" }}
            gap="small"
            className="sd-apikeymanager__row"
          >
            <Stack gap="x-small" className="sd-apikeymanager__details">
              <Stack direction="row" align="center" gap="x-small" wrap className="sd-apikeymanager__head">
                <><h3 className="sd-apikeymanager__label sd-type-body-medium">{key.label}</h3></>
                <Badge>API key</Badge>
              </Stack>
              <>
                <span className="sd-apikeymanager__key sd-type-code-medium">{key.maskedKey}</span>
              </>
              {key.created && (
                <>
                  <span className="sd-apikeymanager__created sd-type-caption-medium">
                    Created {key.created}
                  </span>
                </>
              )}
            </Stack>
            <Button
              type="button"
              variant="secondary"
              size="small"
              aria-label={`Revoke ${key.label}`}
              onPress={() => onRevoke?.(key.id)}
            >
              Revoke
            </Button>
          </Stack>
        ))}
      </Stack>
    </Stack>
  );
}

/* ApiKeyManager.css — .sd-apikeymanager (Block)
   Arrangement only: the create field fills its row and key rows remain readable when narrow. */
.sd-apikeymanager {
  width: 100%;
}

.sd-apikeymanager__label-field {
  flex: 1;
  min-width: 0;
}

.sd-apikeymanager__row {
  padding-block: var(--sd-space-small);
}

.sd-apikeymanager__details {
  min-width: 0;
}

.sd-apikeymanager__label {
  margin: 0;
}

.sd-apikeymanager__key {
  overflow-wrap: anywhere;
}
